class Solution(object):
    def numDecodings(self, s):
        """
        :type s: str
        :rtype: int
        """
        if not s or s[0] == '0':
                return 0
        if len(s) == 1:
                return 1

        dp = [0]*len(s)
        dp[0] = 1

        if int(s[:2]) > 26:
                if s[1] != '0':
                        dp[1] = 1
                else:
                        dp[0] = 0
        else:
                if s[1] != '0':
                        dp[1] = 2
                else:
                        dp[1] = 1

        for index in range(2, len(s)):
                if s[index] != '0':
                        dp[index] += dp[index-1]

                val = int(s[index-1:index+1])
                if val >= 10 and val <= 26:
                        dp[index] += dp[index-2]
        return dp[len(s)-1]

# Time: O(N)
# Space: O(N)

class Solution(object):
    def isInterleave(self, s1, s2, s3):
        """
        :type s1: str
        :type s2: str
        :type s3: str
        :rtype: bool
        """

        if len(s3) != len(s1) + len(s2):
                return False

        dp = [[False for _ in range(len(s2)+1)] for _ in range(len(s1)+1)]
        for row in range(len(s1)+1):
                for col in range(len(s2)+1):
                        if row == 0 and col == 0:
                                dp[row][col] = True 
                        elif row == 0:
                                dp[row][col] =dp[row][col-1] and s2[col-1] == s3[row+col-1]
                        elif col == 0:
                                dp[row][col] = dp[row-1][col] and s1[row-1] == s3[row+col-1]
                        else:
                                dp[row][col] = (dp[row][col-1] and s2[col-1] == s3[row+col-1]) or (dp[row-1][col] and s1[row-1] == s3[row+col-1])

        return dp[len(s1)][len(s2)]

# Time: O(m*n)
# Space: O(m*n)
